function chime(){try{if(!audioCtx||audioCtx.state!=='running')return;[523.25,659.25,783.99].forEach((freq,i)=>{const osc=audioCtx.createOscillator(),gain=audioCtx.createGain(),t=audioCtx.currentTime+i*.2;osc.type='sine';osc.frequency.value=freq;gain.gain.setValueAtTime(0,t);gain.gain.linearRampToValueAtTime(.08,t+.02);gain.gain.exponentialRampToValueAtTime(.001,t+1.4);osc.connect(gain);gain.connect(audioCtx.destination);osc.start(t);osc.stop(t+1.5);});}catch{}}
