function updateClock(){const now=new Date(),h=now.getHours(),hm=now.toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit',hour12:false});$('#live-clock').textContent=hm;const sceneClock=$('#scene-clock');if(sceneClock)sceneClock.textContent=hm;$('#today-date').textContent=now.toLocaleDateString('zh-CN',{month:'long',day:'numeric',weekday:'long'});$('#greeting').firstChild.textContent=`${h<6?'夜深了，记得好好休息。':h<12?'上午好，从容开启新一天。':h<18?'午后好，慢慢来就好。':'晚上好，留一点时间给自己。'}`;}
